// The native settings' protocol, both ends generated by `tool/prepare.sh`:
// the app sends every settings page as the schema builds it, a controller at
// a time as plain data, whenever any of it changed; the client draws each
// row by its kind and says back what the user did, by row id. Every rule —
// which options are on offer, what unset means, what a change sets off — is
// the app's. See "Settings as data" in lib/ui/settings/AGENTS.md.

// ignore_for_file: not_initialized_non_nullable_instance_field

import "package:pigeon/pigeon.dart";

@ConfigurePigeon(
  PigeonOptions(
    dartPackageName: "entoli_glass",
    dartOut: "packages/entoli_glass/lib/src/settings_contract.g.dart",
    swiftOut:
        "packages/entoli_glass/darwin/entoli_glass/Sources/entoli_glass/Contract/SettingsContract.g.swift",
    // The shell's contract, in the same Swift module, declares the one.
    swiftOptions: SwiftOptions(includeErrorClass: false),
  ),
)
/// What a row is: the kind of controller it was sent from, which decides how
/// it is drawn and what may be said back about it.
enum SettingKind {
  toggle,
  choice,
  slots,
  range,
  keyValues,
  action,
  group,
  number,
  modelPick,
  text,
  notice,
  collection,
  catalog,
  info,
  subpage,
  pairing,
  setup,
}

/// How a row would like to be drawn; a client that cannot honour one draws
/// the kind its own way. The schema's `UiHint`, name for name.
enum SettingHint {
  toggle,
  dropdown,
  segmented,
  swatches,
  corners,
  icons,
  levels,
  slider,
  keyValues,
  button,
  row,
  field,
  notice,
  banner,
  card,
  installed,
  single,
  info,
  input,
  paragraph,
  devices,
  buttons,
  recommended,
  providers,
  running,
  models,
  setup,
  permission,
  triggers,
  agents,
  skills,
}

/// What an icon beside a setting stands for: the schema's `SettingGlyph`,
/// name for name. The client picks its own picture for each.
enum SettingIcon {
  deleteForever,
  play,
  stop,
  warning,
  shield,
  appMark,
  person,
  code,
  privacy,
  licence,
  add,
  download,
  upload,
  notificationsOff,
  alarmOff,
  schedule,
  countdown,
  files,
  online,
  connecting,
  offline,
  failed,
}

enum SettingTone { plain, good, warning }

/// The pages a row can open: the schema's `SettingsPageId`, name for name.
enum SettingsPageKey {
  general,
  providers,
  onDevice,
  llms,
  images,
  memory,
  voice,
  triggers,
  agents,
  skills,
  terminal,
  agentBrowser,
  byteRepair,
  sync,
  data,
  welcome,
  shortcuts,
  about,
  syncRelay,
  syncTurn,
  onDeviceLlm,
}

/// One option of a choice, by its place in the list.
class SettingOptionData {
  SettingOptionData({
    required this.label,
    this.detail,
    this.enabled = true,
    this.argb,
    this.argb2,
    this.radius,
    this.appIcon,
  });

  String label;
  String? detail;
  bool enabled;

  /// A swatch's colours, the second splitting it diagonally.
  int? argb;
  int? argb2;

  /// A corner drawn at its own radius.
  double? radius;

  /// One of the app's icons, by name.
  String? appIcon;
}

class SettingGroupData {
  SettingGroupData({required this.label, required this.options});

  String label;
  List<SettingOptionData?> options;
}

/// A paragraph, or a link where it has a [url].
class SettingLineData {
  SettingLineData({required this.text, this.url});

  String text;
  String? url;
}

class SettingItemActionData {
  SettingItemActionData({
    required this.id,
    required this.label,
    this.enabled = true,
    this.destructive = false,
    this.confirm,
  });

  String id;
  String label;
  bool enabled;
  bool destructive;
  SettingConfirmData? confirm;
}

/// One item of a collection, by its place in the list.
class SettingItemData {
  SettingItemData({
    required this.title,
    this.subtitle,
    this.error,
    this.icon,
    this.tone = SettingTone.plain,
    this.on,
    this.actions = const [],
  });

  String title;
  String? subtitle;
  String? error;
  SettingIcon? icon;
  SettingTone tone;

  /// Whether it is armed, where its row carries a switch.
  bool? on;

  List<SettingItemActionData?> actions;
}

/// One thing to download, with the one thing that can be done to it now.
class SettingCatalogData {
  SettingCatalogData({
    required this.id,
    required this.title,
    this.summary,
    this.note,
    this.badge,
    this.tags = const [],
    this.failure,
    this.received,
    this.total,
    this.unpacking = false,
    this.installed = false,
    this.downloadable = true,
    this.updatable = false,
    this.deleteConfirm,
  });

  String id;
  String title;
  String? summary;
  String? note;
  String? badge;
  List<String?> tags;
  String? failure;

  /// Bytes so far and in all, where it is being fetched now.
  int? received;
  int? total;
  bool unpacking;
  bool installed;
  bool downloadable;
  bool updatable;
  SettingConfirmData? deleteConfirm;
}

class SettingInfoData {
  SettingInfoData({
    required this.title,
    this.subtitle,
    this.icon,
    this.keyChar,
    this.keyShift = false,
    this.keyAlt = false,
    this.link,
    this.opens,
  });

  String title;
  String? subtitle;
  SettingIcon? icon;

  /// The chord that does it: the character typed with the chord key.
  String? keyChar;
  bool keyShift;
  bool keyAlt;

  String? link;

  /// A page of the app's own it opens: "privacyPolicy", "licences".
  String? opens;
}

/// A pairing in flight.
class SettingPairingData {
  SettingPairingData({
    required this.stage,
    this.qr,
    this.code,
    this.sas,
    this.peerName,
    this.error,
  });

  /// "connecting", "confirming", "done", "failed".
  String stage;
  String? qr;
  String? code;
  String? sas;
  String? peerName;
  String? error;
}

class SettingToolData {
  SettingToolData({required this.name, this.version});

  String name;
  String? version;
}

/// Everything a row may say, its [kind] saying which of it is meaningful.
class SettingRowData {
  SettingRowData({
    required this.id,
    required this.kind,
    required this.hint,
    required this.title,
    this.detail,
    this.footnote,
    this.enabled = true,
    this.icon,
    this.parent,
    this.accessory = false,
    this.on,
    this.effective = false,
    this.unsettable = false,
    this.options = const [],
    this.picked,
    this.inheritedLabel,
    this.noneLabel,
    this.error,
    this.groups = const [],
    this.slotPicks = const [],
    this.value,
    this.inherited,
    this.stops = const [],
    this.min,
    this.max,
    this.unit,
    this.commitOnEnd = false,
    this.entries = const {},
    this.masked = true,
    this.label,
    this.destructive = false,
    this.secondary = false,
    this.busy = false,
    this.modelLabel,
    this.text,
    this.emptyLabel,
    this.prompt,
    this.secret = false,
    this.lines = 1,
    this.submitLabel,
    this.clearLabel,
    this.notice = const [],
    this.tone = SettingTone.plain,
    this.items = const [],
    this.addLabel,
    this.removeLabel,
    this.removable = true,
    this.editable = false,
    this.emptyItems,
    this.catalog = const [],
    this.info = const [],
    this.page,
    this.summary,
    this.pairing,
    this.canScan = false,
    this.blocked,
    this.setupNotice,
    this.prerequisiteWhy,
    this.prerequisiteCommand,
    this.tools,
    this.running = false,
  });

  String id;
  SettingKind kind;
  SettingHint hint;
  String title;
  String? detail;
  String? footnote;
  bool enabled;
  SettingIcon? icon;

  /// The row this one belongs to: a group's own, or the row it is drawn at
  /// the end of where [accessory]. Such a row comes after its parent in the
  /// section's list and is drawn as part of it, not on its own.
  String? parent;
  bool accessory;

  // toggle
  bool? on;
  bool effective;
  bool unsettable;

  // choice, slots
  List<SettingOptionData?> options;

  /// The option picked, by its place; null for none, or unset.
  int? picked;
  String? inheritedLabel;
  String? noneLabel;
  String? error;
  List<SettingGroupData?> groups;

  /// Each slot's pick, by its place among every group's options in order.
  List<int?> slotPicks;

  // range, number
  int? value;
  int? inherited;
  List<int?> stops;
  int? min;
  int? max;
  String? unit;
  bool commitOnEnd;

  // keyValues
  Map<String?, String?> entries;
  bool masked;

  // action
  String? label;
  bool destructive;
  bool secondary;

  // group: its rows are the ones naming it their parent
  bool busy;

  // modelPick
  String? modelLabel;

  // text
  String? text;
  String? emptyLabel;
  String? prompt;
  bool secret;
  int lines;
  String? submitLabel;
  String? clearLabel;

  // notice
  List<SettingLineData?> notice;
  SettingTone tone;

  // collection
  List<SettingItemData?> items;
  String? addLabel;
  String? removeLabel;
  bool removable;

  /// Whether items are added and edited through a form.
  bool editable;
  String? emptyItems;

  // catalog
  List<SettingCatalogData?> catalog;

  // info
  List<SettingInfoData?> info;

  // subpage
  SettingsPageKey? page;
  String? summary;

  // pairing
  SettingPairingData? pairing;
  bool canScan;

  // setup
  String? blocked;
  String? setupNotice;
  String? prerequisiteWhy;
  String? prerequisiteCommand;
  List<SettingToolData?>? tools;
  bool running;
}

class SettingsSectionData {
  SettingsSectionData({
    required this.id,
    required this.title,
    this.detail,
    this.rows = const [],
  });

  String id;
  String title;
  String? detail;
  List<SettingRowData?> rows;
}

class SettingsPageData {
  SettingsPageData({
    required this.key,
    required this.title,
    this.groupStart = false,
    this.listed = true,
    this.sections = const [],
  });

  SettingsPageKey key;
  String title;
  bool groupStart;
  bool listed;
  List<SettingsSectionData?> sections;
}

/// Every page this platform offers, as it stands.
class SettingsSnapshot {
  SettingsSnapshot({required this.pages});

  List<SettingsPageData?> pages;
}

/// What an action asks before it runs.
class SettingConfirmData {
  SettingConfirmData({
    required this.title,
    required this.message,
    this.confirmLabel,
    this.destructive = false,
    this.brief = false,
    this.cancelled = false,
  });

  String title;
  String message;

  /// Null: nothing to confirm, only something to say; the action stops.
  String? confirmLabel;
  bool destructive;

  /// Said in passing, and the action stops.
  bool brief;

  /// Nothing to say, and the action stops.
  bool cancelled;
}

class SettingNoticeData {
  SettingNoticeData({required this.message, this.title});

  String? title;
  String message;
}

enum FormPartKind { question, text, choice, date, duration, list, multi, note }

class FormPartData {
  FormPartData({
    required this.kind,
    this.id,
    this.label,
    this.hint,
    this.helper,
    this.error,
    this.focused = false,
    this.lines = 1,
    this.options = const [],
    this.enabled = true,
    this.segmented = false,
  });

  FormPartKind kind;
  String? id;

  /// A question's text, or a field's label.
  String? label;
  String? hint;
  String? helper;
  String? error;
  bool focused;
  int lines;

  /// A choice's options, each the answer it stores and its label and help.
  List<FormOptionData?> options;

  bool enabled;

  /// A choice drawn with every option side by side.
  bool segmented;
}

class FormOptionData {
  FormOptionData({required this.answer, required this.label, this.help});

  String answer;
  String label;
  String? help;
}

/// A form as it stands for [answers]: the fields to ask, and what stops it
/// being saved.
class SettingFormData {
  SettingFormData({
    required this.title,
    required this.answers,
    required this.parts,
    this.problem,
    this.savable = false,
  });

  String title;
  Map<String?, String?> answers;
  List<FormPartData?> parts;
  String? problem;
  bool savable;
}

/// What the app says to the client.
@HostApi(dartHostTestHandler: "TestNativeSettings")
abstract class NativeSettings {
  /// Every page, replacing what the client held.
  void settings(SettingsSnapshot snapshot);

  /// Show the settings, at [page] where it names one.
  void show(SettingsPageKey? page);
}

/// What the client says the user did, by row id. A row inside a group is
/// named by its own id. The answers that wait return what the client shows
/// next: a confirm, a notice, a form.
@FlutterApi()
abstract class SettingsIntents {
  void toggle(String id, bool? on);

  /// Picks [option] by its place, or nothing.
  void pick(String id, int? option);

  void pickSlot(String id, int slot, int option);

  void setNumber(String id, int? value);

  void setText(String id, String text);

  void putEntry(String id, String name, String value, String? replacing);

  void removeEntry(String id, String name);

  void setModel(String id, String? providerId, String? modelId);

  /// What [id]'s action asks before it runs, or null to run it now.
  @async
  SettingConfirmData? ask(String id);

  /// Runs [id]'s action, once what it asked was agreed to.
  @async
  SettingNoticeData? run(String id);

  @async
  SettingNoticeData? itemAction(String id, int index, String action);

  void removeItem(String id, int index);

  /// The form for the item at [index], or a new one, as [answers] stand;
  /// null answers are its first.
  @async
  SettingFormData form(String id, int? index, Map<String?, String?>? answers);

  @async
  SettingNoticeData? submitForm(
    String id,
    int? index,
    Map<String?, String?> answers,
  );

  /// [op] is "download", "cancel" or "delete".
  void catalog(String id, String item, String op);

  /// [op] is "openWindow", "closeWindow", "cancel", "match" or "mismatch".
  void pairing(String id, String op);

  /// Pairs with [code], a code or an invite's answer.
  @async
  String? pairWith(String id, String code);

  @async
  String createInvite(String id);

  /// [op] is "setUp", "import" or "delete".
  void setup(String id, String op);

  /// A model picker's entries, every one the role can use: each "providerId
  /// \u0000modelId\u0000label\u0000section".
  @async
  List<String> models(String id);

  /// The text of a page the app holds: the privacy policy, the licences.
  @async
  String page(String opens);
}
